package org.apache.commons.text.similarity;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class LongestCommonSubsequence_ESTest_test09 extends LongestCommonSubsequence_ESTest_scaffolding {

    /**
     * Verifies that {@link LongestCommonSubsequence#apply(CharSequence, CharSequence)}
     * rejects a null second argument by throwing an {@link IllegalArgumentException},
     * even when the first argument is a valid (non-null) character sequence.
     */
    @Test(timeout = 4000)
    public void applyWithNullRightInputThrowsIllegalArgumentException() throws Throwable {
        LongestCommonSubsequence lcs = LongestCommonSubsequence.INSTANCE;

        // A non-null sequence of 18 NUL characters; the exact content is irrelevant
        // because the null right argument is rejected before any comparison happens.
        CharSequence nonNullLeft =
                "���������"
                + "���������";
        CharSequence nullRight = null;

        try {
            lcs.apply(nonNullLeft, nullRight);
            fail("Expecting exception: IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // Inputs must not be null
            verifyException("org.apache.commons.text.similarity.LongestCommonSubsequence", e);
        }
    }
}
